const assets = {"/index.html":{"type":"text/html; charset=utf-8","body":""},"/sw.js":{"type":"application/javascript; charset=utf-8","body":""},"/manifest.webmanifest":{"type":"application/manifest+json","body":""},"/icon.svg":{"type":"image/svg+xml","body":""},"/icon-192.png":{"type":"image/png","body":""},"/icon-512.png":{"type":"image/png","body":""}};
